--[[
    MUZAN AVATAR EDIT  |  by NOX
    Every Muzan shot is replaced by YOUR current avatar
    (whatever outfit / accessories / body colors you're wearing right now).

    The video is embedded in this script (~6 MB). Just execute it.
    A loading screen shows while it prepares, then the edit starts.
]]


local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local StarterGui = game:GetService("StarterGui")
local TweenService = game:GetService("TweenService")
local lp = Players.LocalPlayer

local function notify(text)
	pcall(function()
		StarterGui:SetCore("SendNotification", {Title = "NOX EDIT", Text = text, Duration = 5})
	end)
end

-- remove an older copy if executed twice
pcall(function()
	local old = ((gethui and gethui()) or game:GetService("CoreGui")):FindFirstChild("NOXMuzanEdit")
	if old then old:Destroy() end
end)
pcall(function()
	local old = lp.PlayerGui:FindFirstChild("NOXMuzanEdit")
	if old then old:Destroy() end
end)

----------------------------------------------------------------
-- GUI (built first so the loading screen shows immediately)
----------------------------------------------------------------
local gui = Instance.new("ScreenGui")
gui.Name = "NOXMuzanEdit"
gui.IgnoreGuiInset = true
gui.ResetOnSpawn = false
gui.DisplayOrder = 999999
gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
pcall(function()
	gui.Parent = (gethui and gethui()) or game:GetService("CoreGui")
end)
if not gui.Parent then
	gui.Parent = lp:WaitForChild("PlayerGui")
end

local closed = false
local conn

local back = Instance.new("Frame")
back.Size = UDim2.fromScale(1, 1)
back.BackgroundColor3 = Color3.new(0, 0, 0)
back.BorderSizePixel = 0
back.Parent = gui

-- 9:16 stage (same shape as the original video)
local stage = Instance.new("Frame")
stage.AnchorPoint = Vector2.new(0.5, 0.5)
stage.Position = UDim2.fromScale(0.5, 0.5)
stage.Size = UDim2.fromScale(1, 1)
stage.BackgroundTransparency = 1
stage.ClipsDescendants = true
stage.Parent = back

local ratio = Instance.new("UIAspectRatioConstraint")
ratio.AspectRatio = 720 / 1280
ratio.AspectType = Enum.AspectType.FitWithinMaxSize
ratio.Parent = stage

local video = Instance.new("VideoFrame")
video.Size = UDim2.fromScale(1, 1)
video.BackgroundTransparency = 1
video.Looped = false
video.Volume = 1
video.ZIndex = 1
video.Parent = stage

-- the part of the video where the anime footage lives (black bars stay untouched)
local band = Instance.new("Frame")
band.Position = UDim2.fromScale(0, 0.293)
band.Size = UDim2.fromScale(1, 0.415)
band.BackgroundTransparency = 1
band.ClipsDescendants = true
band.ZIndex = 2
band.Visible = false
band.Parent = stage

-- holder = the box where the avatar is drawn (full band or a small box for far shots)
local holder = Instance.new("Frame")
holder.AnchorPoint = Vector2.new(0.5, 0.5)
holder.Position = UDim2.fromScale(0.5, 0.5)
holder.Size = UDim2.fromScale(1, 1)
holder.BackgroundColor3 = Color3.fromRGB(8, 28, 52)
holder.BorderSizePixel = 0
holder.ClipsDescendants = true
holder.ZIndex = 3
holder.Parent = band

local holderCorner = Instance.new("UICorner")
holderCorner.CornerRadius = UDim.new(0, 0)
holderCorner.Parent = holder

-- moving blue "mist" background so the swapped shots keep the same look
local grad = Instance.new("UIGradient")
grad.Color = ColorSequence.new({
	ColorSequenceKeypoint.new(0, Color3.fromRGB(4, 14, 30)),
	ColorSequenceKeypoint.new(0.5, Color3.fromRGB(18, 70, 120)),
	ColorSequenceKeypoint.new(1, Color3.fromRGB(6, 24, 46)),
})
grad.Parent = holder

local vp = Instance.new("ViewportFrame")
vp.Size = UDim2.fromScale(1, 1)
