local FORMATS = {
	{name = "webm", file = "nox_muzan_edit_v5.webm", size = 3384685, chunks = chunksWebm},
	{name = "mp4", file = "nox_muzan_edit_v5.mp4", size = 2773670, chunks = chunksMp4},
}

local function prepareFile(fmt, p0, p1)
	if not (isfile and writefile and readfile and getasset) then
		error("Your executor has no file functions (writefile / getcustomasset)")
	end
	local good = false
	if isfile(fmt.file) then
		local rok, content = pcall(readfile, fmt.file)
		good = rok and type(content) == "string" and #content == fmt.size
	end
	if not good then
		setProgress(p0, "Unpacking " .. fmt.name .. " video (first run only)")
		local data = decodeB64(fmt.chunks(), fmt.size, function(f)
			setProgress(p0 + f * (p1 - p0), "Unpacking " .. fmt.name .. " video (first run only)")
		end)
		if closed or not data then return nil end
		if #data ~= fmt.size then
			error("Video unpack failed (" .. fmt.name .. " wrong size " .. #data .. ")")
		end
		setProgress(p1, "Saving " .. fmt.name .. " video")
		writefile(fmt.file, data)
	end
	return getasset(fmt.file)
end

-- try to load one format into the VideoFrame; true if it loaded
local function tryLoad(fmt, p0, p1, label)
	local asset = prepareFile(fmt, p0, p0 + (p1 - p0) * 0.6)
	if closed or not asset then return false end
	local base = p0 + (p1 - p0) * 0.6
	setProgress(base, label .. " (" .. fmt.name .. ")")
	pcall(function() video:Stop() end)
	video.Volume = 0
	video.Video = asset
	pcall(function() video:Play() end)   -- some executors only load after Play
	local waited = 0
	while not closed and waited < 12 do
		if video.IsLoaded or video.TimePosition > 0.05 then
			pcall(function() video:Pause() end)
			video.TimePosition = 0
			video.Volume = 1
			return true
		end
		task.wait(0.2)
		waited += 0.2
		setProgress(base + math.min(waited / 12, 1) * (p1 - base) * 0.95)
	end
	pcall(function() video:Stop() end)
	pcall(function() video.Video = "" end)
	return false
end

----------------------------------------------------------------
-- SHOTS (timed to the original video)
-- Character faces -Z, so a camera at negative Z sees the front.
----------------------------------------------------------------
local V3, CF = Vector3.new, CFrame.lookAt

local shots = {
	-- 0-4s: far shot at the gate
	{t0 = 0, t1 = 4, box = {pos = UDim2.fromScale(0.42, 0.36), size = UDim2.fromScale(0.22, 0.45)},
		cam = function(p)
			return CF(V3(0.5 - p, 3.6, -15), V3(0, 3, 0)), 32
		end},
	-- 4-8s: foot close-up
	{t0 = 4, t1 = 8, bob = true,
		cam = function(p)
			return CF(V3(-4.5 + p * 1.2, 0.9, -2 + p), V3(0, 0.5, -0.2)), 55
		end},
	-- 8-10s: walking with coat flowing
	{t0 = 8, t1 = 10, bob = true,
		cam = function(p)
			return CF(V3(-6 + p * 2.5, 3, -8), V3(0, 3.2, 0)), 50
		end},
	-- 10-13s: face close-up (roar), slow push-in
	{t0 = 10, t1 = 13,
		cam = function(p)
			return CF(V3(0, 5.7, -4.6 + p * 1.6), V3(0, 5.5, 0)) * CFrame.Angles(0, 0, math.rad(-6 + p * 6)), 45
		end},
	-- 13-15s: from above / behind
	{t0 = 13, t1 = 15,
		cam = function(p)
			return CF(V3(0, 12, 6 - p), V3(0, 3, 0)), 50
		end},
	-- 15-18s: legs on gravel
	{t0 = 15, t1 = 18, bob = true,
		cam = function(p)
			return CF(V3(2 - p, 1.6, 6), V3(0, 1.6, 0)), 55
		end},
	-- 18-22s: feet on the wooden step
	{t0 = 18, t1 = 22, bob = true,
		cam = function(p)
			return CF(V3(-5, 0.6, -0.8 + p * 1.2), V3(0, 0.4, 0)), 55
		end},
	-- 22-26s: far shot by the water
	{t0 = 22, t1 = 26, box = {pos = UDim2.fromScale(0.30, 0.44), size = UDim2.fromScale(0.20, 0.48)},
		cam = function(p)
			return CF(V3(0.5 - p * 0.5, 3.6, -15), V3(0, 3, 0)), 32
		end},
	-- 26-end: final portrait, slow push-in
	{t0 = 26, t1 = 99,
		cam = function(p, t)
			local push = math.clamp((t - 26) / 4, 0, 1)
			return CF(V3(0, 5, -6 + push * 1.6), V3(0, 4.7, 0)), 40
		end},
}

local current
local function applyShot(s)
	current = s
	if s.box then
		holder.Position = s.box.pos
		holder.Size = s.box.size
		holderCorner.CornerRadius = UDim.new(1, 0)
	else
		holder.Position = UDim2.fromScale(0.5, 0.5)
		holder.Size = UDim2.fromScale(1, 1)
		holderCorner.CornerRadius = UDim.new(0, 0)
	end
end

----------------------------------------------------------------
-- MAIN
----------------------------------------------------------------
local function step(name, fn)
	local ok, e = pcall(fn)
	if not ok then
		error("[" .. name .. "] " .. tostring(e), 0)
	end
end

local function main()
	-- 2) copy the executor's avatar (current outfit)
	setProgress(0.05, "Copying your avatar")
	local char = lp.Character or lp.CharacterAdded:Wait()
	char:WaitForChild("HumanoidRootPart")
	task.wait(0.2)
	local wasArchivable = char.Archivable
	char.Archivable = true
	local avatar = char:Clone()
	char.Archivable = wasArchivable
	if not avatar then
		error("Couldn't copy your avatar")
	end
	for _, d in ipairs(avatar:GetDescendants()) do
		if d:IsA("Script") or d:IsA("LocalScript") then d:Destroy() end
	end
	for _, d in ipairs(avatar:GetDescendants()) do
		if d:IsA("BasePart") then
			d.Anchored = true
			d.CanCollide = false
		end
	end
	local hum = avatar:FindFirstChildOfClass("Humanoid")
	if hum then
		hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
	end
	avatar.Parent = vp
	avatar:PivotTo(CFrame.new(0, 3, 0))
	setProgress(0.14, "Avatar ready")

	-- 3) load video into the player (webm, then mp4; then retry from PlayerGui)
	local loaded = false
	local attempt = 0
	local rounds = {"current", "playergui"}
	for _, round in ipairs(rounds) do
		if round == "playergui" then
			if gui.Parent == lp:FindFirstChild("PlayerGui") then break end
			pcall(function() gui.Parent = lp:WaitForChild("PlayerGui") end)
		end
		for _, fmt in ipairs(FORMATS) do
			attempt += 1
			local p0 = 0.15 + (attempt - 1) * 0.18
			local p1 = p0 + 0.18
			if tryLoad(fmt, p0, p1, "Loading video") then
				loaded = true
				break
			end
			if closed then return end
		end
		if loaded then break end
	end
	if closed then return end
	if not loaded then
		local exec = "unknown"
		pcall(function() exec = tostring(identifyexecutor()) end)
		error("Video didn't load in webm or mp4. Executor: " .. exec .. ". This executor probably can't play custom video files.")
	end

	-- 4) ready: start the edit
	setProgress(1, "Ready")
	task.wait(0.5)
	step("set time", function() video.TimePosition = 0 end)
	step("first shot", function() applyShot(shots[1]) end)
	step("show edit", function() band.Visible = true end)
	step("play video", function() video:Play() end)

	pcall(function()
		TweenService:Create(loading, TweenInfo.new(0.6), {GroupTransparency = 1}):Play()
	end)
	task.delay(0.7, function()
		if not errored and loading.Parent then loading:Destroy() end
	end)

	video.Ended:Connect(function()
		if video.TimePosition < 3 then
			task.spawn(fail, "Video stopped right away (it loaded but can't play on this executor)")
			return
		end
		task.wait(0.6)
		cleanup()
	end)

	-- make sure it is really playing
	task.delay(6, function()
		if not closed and not errored and video.TimePosition < 0.1 then
			fail("Video loaded but isn't playing (time stays at 0). Executor can't play custom video.")
		end
	end)

	-- small red debug line, only shows if something breaks while playing
	local dbg = Instance.new("TextLabel")
	dbg.Size = UDim2.new(1, 0, 0, 40)
	dbg.Position = UDim2.new(0, 0, 1, -40)
	dbg.BackgroundTransparency = 1
	dbg.TextColor3 = Color3.fromRGB(255, 90, 90)
	dbg.TextSize = 12
	dbg.TextWrapped = true
	dbg.Font = Enum.Font.Gotham
	dbg.Text = ""
	dbg.ZIndex = 400
	dbg.Parent = gui

	local lastErr
	local function frame()
		local t = video.TimePosition
		local shot = shots[#shots]
		for _, s in ipairs(shots) do
			if t >= s.t0 and t < s.t1 then
				shot = s
				break
			end
		end
		if shot ~= current then applyShot(shot) end

		local p = math.clamp((t - shot.t0) / (shot.t1 - shot.t0), 0, 1)
		local cf, fov = shot.cam(p, t)
		cam.CFrame = cf
		cam.FieldOfView = fov

		local bob = shot.bob and math.abs(math.sin(t * 7)) * 0.18 or 0
		avatar:PivotTo(CFrame.new(0, 3 + bob, 0))
		grad.Rotation = (t * 25) % 360
	end

	conn = RunService.RenderStepped:Connect(function()
		local ok, e = pcall(frame)
		if not ok and e ~= lastErr then
			lastErr = e
			dbg.Text = "frame error: " .. tostring(e)
			warn("[NOX EDIT] frame error: " .. tostring(e))
		end
	end)
end

task.spawn(function()
	local ok, err = pcall(main)
	if not ok then
		fail(tostring(err))
	end
end)
